objects.declaration:
PROGRAM PLC_PRG
VAR
    Counter : DINT;
    Result : DINT;
    fb : FB_Add;
END_VAR

objects.implementation:
Counter := Counter + 1;
fb(Value := Counter);
Result := fb.Result;

IF GVL_Test.Enable THEN
    Result := Value + GVL_Test.Step;
ELSE
    Result := Value;
END_IF;

objects.declaration:
VAR_GLOBAL
    Enable : BOOL := FALSE;
    Step : DINT := 1;
END_VAR
